 const normal=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
 const euSource='https://europa.eu/youreurope/citizens/travel/security-and-emergencies/emergency/index_en.htm';
 const euNames={es:'Unión Europea',en:'European Union',fr:'Union européenne',de:'Europäische Union',pt:'União Europeia',eu:'Europar Batasuna',hi:'यूरोपीय संघ',zh:'欧盟',ru:'Европейский союз',ja:'欧州連合',ar:'الاتحاد الأوروبي'};
