 const countries=Object.freeze(data.countries.map(country=>Object.freeze({...country,services:Object.freeze(country.services.map(Object.freeze))})));
 const byId=new Map(countries.map(country=>[country.id,country])),displayNames=new Map(),searchIndexes=new Map();
 function name(country,lang='es'){
  if(!country)return '';if(country.id==='EU')return euNames[lang]||euNames.en;
  if(country.group)return country.name;
  try{if(!displayNames.has(lang))displayNames.set(lang,new Intl.DisplayNames([lang],{type:'region',fallback:'none'}));return displayNames.get(lang).of(country.id)||country.name;}catch(_){return country.name;}
 }
 function get(id){return id==='EU'?eu:byId.get(id)||null;}
 function list(lang='es'){return [...countries].sort((a,b)=>name(a,lang).localeCompare(name(b,lang),lang));}
 function search(query,lang='es'){
  const needle=normal(query);return list(lang).filter(country=>{if(!searchIndexes.has(country.id))searchIndexes.set(country.id,normal([country.id,country.name,...Object.keys(euNames).map(l=>name(country,l)),...country.aliases].join(' ')));return searchIndexes.get(country.id).includes(needle);});
 }
 function tel(number){const value=String(number||'').replace(/[ ()-]/g,'');return /^\+?\d{2,15}$/.test(value)?'tel:'+value:null;}
 function prefix(country){return callingCodes[country]?'+'+callingCodes[country]:'';}
 function suggest(value){const code=String(value||'').trim().replace(/^00/,'+');if(!/^\+[1-9]\d{0,2}$/.test(code))return[];return Object.keys(callingCodes).filter(id=>prefix(id)===code);}
 function reference(id,lang='es'){
  const country=get(id);if(!country)return null;
  if(country.eu)return{number:'112',region:euNames[lang]||euNames.en,kind:'general',source:euSource,qualifier:''};
  // A printed medical card must not relabel a police-only number as general medical help.
  const order=['general','ambulance','ambulance_fire','police_ambulance'];let service;
  for(const kind of order){service=country.services.find(x=>x.kind===kind&&!x.qualifier&&/^\d{2,5}$/.test(x.number));if(service)break;}
  if(!service)return null;
  return{number:service.number,region:name(country,lang),kind:service.kind,source:country.source,qualifier:service.qualifier};
 }
